def intersect(a,b,c,d):
 x,y=a;u,v=b[0]-x,b[1]-y;p,q=c;r,s=d[0]-p,d[1]-q;det=u*s-v*r
 t=((p-x)*s-(q-y)*r)/det;w=((p-x)*v-(q-y)*u)/det
 return [x+t*u,y+t*v],t,w
